SELECT (SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL AND p.gender = 'F' AND EXTRACT(YEAR FROM p.dod) = EXTRACT(YEAR FROM CURRENT_DATE) - 62 AND EXTRACT(YEAR FROM a.intime) BETWEEN 2017 AND 2018 AND a.los <= 7 AND d.charlson <= 5 THEN 1 END) AS FLOAT) / NULLIF((SELECT COUNT(CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM p.dod) = EXTRACT(YEAR FROM CURRENT_DATE) - 62 AND EXTRACT(YEAR FROM a.intime) BETWEEN 2017 AND 2018 AND a.los > 7 AND d.charlson > 5 THEN 1 END), 0) AS proportion FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.dod IS NOT NULL AND p.gender = 'F' AND EXTRACT(YEAR FROM p.dod) = EXTRACT(YEAR FROM CURRENT_DATE) - 62 AND EXTRACT(YEAR FROM a.intime) BETWEEN 2017 AND 2018 AND a.los <= 7 AND d.charlson <= 5) AS proportion_of_patients_with_sepsis_without_shock_and_los_less_than_or_equal_to_seven_days_and_charlson_less_than_or_equal_to_three_quarters_or_five_and_died_within_a_year_of_admission AS proportion_of_patients_with_sepsis_without_shock_and_los_less_than_or_equal_to_seven_days_and_charlson_less_than_or_equal_to_three_quarters_or_five_and_died_within_a_year_of_admission, (SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL AND p.gender = 'F' AND EXTRACT(YEAR FROM p.dod) = EXTRACT(YEAR FROM CURRENT_DATE) - 62 AND EXTRACT(YEAR FROM a.intime) BETWEEN 2017 AND 2018 AND a.los > 7 AND d.charlson > 5 THEN 1 END) AS FLOAT) / NULLIF((SELECT COUNT(CASE WHEN p.gender = 'F' AND EXTRACT(YEAR FROM p.dod) = EXTRACT(YEAR FROM CURRENT_DATE) - 62 AND EXTRACT(YEAR FROM a.intime) BETWEEN 2017 AND 2018 AND a.los > 7 AND d.charlson > 5 THEN 1 END), 0) AS proportion FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.dod IS NOT NULL AND p.gender = 'F' AND EXTRACT(YEAR FROM p.dod) = EXTRACT(YEAR FROM CURRENT_DATE) - 62 AND EXTRACT(YEAR FROM a.intime) BETWEEN 2017 AND 2018 AND a.los > 7 AND d.charlson > 5) AS proportion_of_patients_with